/**
 * Glass doors section /sklyani-dveri/{slug}/ in the shared catalog format
 * (rendered by src/components/profile/ProfileCategoryPage.astro). Hub:
 * src/pages/sklyani-dveri/index.astro. Replaces the programmatic
 * /poslugy/sklyani-dveri/* pages (same slugs, moved under /sklyani-dveri/).
 *
 * Content is Space Glass's own wording. Market facts (glass 8–12 mm, weight per m²,
 * edge types, safety glass, decoration) were checked against Ukrainian glass-door
 * makers' public pages in 2026-09; no competitor text or photos are used —
 * every image is a real Space Glass project (public/images/projects → catalog/sklyani-dveri).
 * Cards describe door configurations, not branded systems, so no prices are shown.
 */
import type { ProfileCategory, ProfileModel } from './profile-systems';

