const PROCESS: [string, string][] = [['Запит', 'Фото та розміри прорізу'], ['Консультація', 'Тип дверей, скло, фурнітура'], ['Замір', 'Проріз, стіни, підлога'], ['Креслення', 'Отвори під фурнітуру'], ['Виготовлення', 'Різання, гартування, декор'], ['Монтаж', 'Встановлення й регулювання']];

type DoorPage = Omit<ProfileCategory, 'group' | 'path' | 'heroImage' | 'imageBase' | 'process' | 'compareColumns' | 'eyebrow'> & { eyebrow: string };

const page = (p: DoorPage): ProfileCategory => {
  if (p.models.length !== 6 || p.faq.length !== 8) throw new Error(`door page ${p.slug}: expected 6 models and 8 own FAQs`);
  return {
    ...p,
    group: 'doors',
    path: P(p.slug),
    eyebrow: `Скляні двері / ${p.eyebrow}`,
    heroImage: `hero-${p.slug}`,
    imageBase: DOORS_IMG,
    process: PROCESS,
    compareColumns: ['Варіант', 'Відкривання', 'Скло', 'Особливість', 'Для чого'],
    faq: [...p.faq, ...COMMON],
    catalogButton: 'Переглянути варіанти',
    optionsLabel: 'Варіант',
    catalogNote: 'Параметри наведені для типових конфігурацій. Максимальні розміри та вага полотна залежать від обраної фурнітури й стін — остаточно визначаємо після заміру. Вартість — за індивідуальним розрахунком.'
  };
};

